#!/usr/bin/env bash
set -euo pipefail
command -v psql >/dev/null||{ echo 'PostgreSQL 16+ psql is required';exit 2;}; major=$(psql --version|sed -E 's/.* ([0-9]+).*/\1/');((major>=16))||exit 2
DB="citem_phase2_2b1_$$";tmp=$(mktemp);trap 'rm -f "$tmp";dropdb --if-exists "$DB" >/dev/null 2>&1||true' EXIT;createdb "$DB"
psql -v ON_ERROR_STOP=1 -d "$DB" <<'SQL' >/dev/null
do $$begin create role authenticated;exception when duplicate_object then null;end$$;do $$begin create role service_role;exception when duplicate_object then null;end$$;do $$begin create role anon;exception when duplicate_object then null;end$$;create schema extensions;create extension pgcrypto with schema extensions;create schema auth;create table auth.users(id uuid primary key,raw_user_meta_data jsonb not null default '{}');create function auth.uid()returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;create function auth.jwt()returns jsonb language sql stable as $$select '{}'::jsonb$$;create schema storage;create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,owner uuid);create function storage.foldername(name text)returns text[] language sql immutable as $$select string_to_array(name,'/')$$;create function storage.filename(name text)returns text language sql immutable as $$select(string_to_array(name,'/'))[array_length(string_to_array(name,'/'),1)]$$;
SQL
find supabase/migrations -maxdepth 1 -name '*.sql'|sort|head -24|while read -r m;do printf "\\i '%s/%s'\n" "$PWD" "$m";done >"$tmp";psql -v ON_ERROR_STOP=1 -d "$DB" -f "$tmp" >/dev/null
psql -v ON_ERROR_STOP=1 -d "$DB" <<'SQL' >/dev/null
insert into auth.users(id)values('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');insert into projects(id,owner_id,name,research_type)values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','AA','CTI'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','BB','CTI'),('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000002','CC','CTI');
insert into research_feed_sources(id,project_id,name,configured_url,configured_url_hash,created_by)values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','A','https://a.example/rss',repeat('a',64),'10000000-0000-4000-8000-000000000001'),('30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','B','https://b.example/rss',repeat('b',64),'10000000-0000-4000-8000-000000000001');
insert into research_items(id,project_id,title,first_seen_at,last_seen_at,created_by)values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','old','2026-01-01','2026-01-02','10000000-0000-4000-8000-000000000001'),('40000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','dup','2026-01-02','2026-01-03','10000000-0000-4000-8000-000000000001');insert into research_item_fingerprints(project_id,research_item_id,fingerprint_type,fingerprint_hash)values('20000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','URL',repeat('c',64)),('20000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000002','URL',repeat('c',64));
SQL
psql -v ON_ERROR_STOP=1 -d "$DB" -f supabase/migrations/202607310025_phase2_2b_osint_intelligence_feed.sql >/dev/null
psql -v ON_ERROR_STOP=1 -d "$DB" -f supabase/migrations/202607310026_phase2_2b1_json_feed_support.sql >/dev/null
psql -v ON_ERROR_STOP=1 -d "$DB" <<'SQL' >/dev/null
do $$declare f research_feed_sources;c record;begin if(select count(*) from research_items where owner_id='10000000-0000-4000-8000-000000000001')<>1 then raise exception 'dedup failed';end if;if(select project_id from research_items limit 1)is null then raise exception 'legacy provenance lost';end if;f:=create_global_research_feed('10000000-0000-4000-8000-000000000001','Global','','https://global.example/rss',repeat('d',64),true,true,15);if f.project_id is not null or f.next_scheduled_fetch_at is null then raise exception 'global schedule failed';end if;select * into c from claim_global_research_feed_fetch(f.owner_id,f.id,'MANUAL');if(select trigger_type from research_feed_fetch_runs where id=c.run_id)<>'MANUAL'then raise exception 'manual trigger missing';end if;perform fail_global_research_feed_fetch(f.owner_id,f.id,c.run_id,c.lease_token,c.request_url_hash,'CONNECTION_TIMEOUT','safe');if(select fetch_lease_run_id from research_feed_sources where id=f.id)is not null then raise exception 'lease not released';end if;update research_feed_sources set next_scheduled_fetch_at=clock_timestamp() where id=f.id;select * into c from claim_due_global_research_feed_fetches(20)limit 1;if(select trigger_type from research_feed_fetch_runs where id=c.run_id)<>'SCHEDULED'then raise exception 'scheduled trigger missing';end if;perform complete_global_research_feed_fetch(c.owner_id,c.feed_source_id,c.run_id,c.lease_token,c.request_url_hash,'SUCCEEDED','JSON_FEED',c.configured_url,200,2,null,null,'[]');if(select detected_feed_type from research_feed_sources where id=c.feed_source_id)<>'JSON_FEED'then raise exception 'json type missing';end if;end$$;
do $$begin if not exists(select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='research_feed_type' and e.enumlabel='JSON_FEED')then raise exception 'enum missing';end if;begin perform 'ARBITRARY'::research_feed_type;raise exception 'arbitrary accepted';exception when invalid_text_representation then null;end;end$$;
SQL
printf 'PostgreSQL %s; migrations 001-026, JSON_FEED completion, provenance, owner dedup, global workflow and exact lease assertions passed.\n' "$(psql -Atqc 'show server_version' -d "$DB")"
